#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Reproduit les notices/visualisations originales à partir du corpus vérifié.

Les sources et crédits sont conservés dans assets/explorer-v2/sources.
Ce script n'utilise aucun réseau. Les cartes historiques sont préparées séparément.
"""
import portable_io
from pathlib import Path
import json
from html import escape as e
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'assets/explorer-v2'
def dump(name,value):
    (OUT/name).write_text(json.dumps(value,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
def src(title,url):return {'title':title,'url':url}
NASA=src('NASA Earth Observatory · World of Change: Shrinking Aral Sea','https://science.nasa.gov/earth/earth-observatory/world-of-change/aral-sea/')
CORNELL=src('Conrad et Kobildjanova, The Economics of an Environmental Disaster: The Aral Sea (2011), p. 1 et tableau 1 p. 6','https://www.cs.cornell.edu/courses/cs6702/2011sp/readings/AralSea2011.pdf')
ICWC=src('SIC ICWC · Basic indicators of water and land use in the Aral Sea basin','https://cawater-info.net/bk/water_land_resources_use/english/docs/table6.pdf')
UNDP=src('PNUD Ouzbékistan · Étude des tempêtes de poussières, 7 mai 2025','https://www.undp.org/uzbekistan/press-releases/undp-and-uzbekistan-join-forces-combat-dust-storms-southern-aral-sea-region')
WB=src('Banque mondiale · Feature Stories, n° 23, octobre 2008','https://documents1.worldbank.org/curated/en/888771468089960580/pdf/462360BRI0Box31e0no0FS231Kazakhstan.pdf')
MOY=src('Wikimedia Commons · Moynaq Aral-Sea Ships','https://commons.wikimedia.org/wiki/File:Moynaq_Aral-Sea_Ships.jpg')
NE=src('Natural Earth · fleuves à 1:50 millions (domaine public)','https://github.com/nvkelso/natural-earth-vector/blob/ca96624a56bd078437bca8184e78163e5039ad19/geojson/ne_50m_rivers_lake_centerlines.geojson')
BYSA='https://creativecommons.org/licenses/by-sa/3.0/'
NASARIGHTS='https://www.nasa.gov/nasa-brand-center/images-and-media/'

def bars(years,values,unit,maxv,caption):
    paths=[]
    for i,(year,v) in enumerate(zip(years,values)):
        x=95+i*96;h=v/maxv*190
        paths.append(f'<rect x="{x}" y="{235-h:.2f}" width="48" height="{h:.2f}" rx="3" fill="#166d71"/><text x="{x+24}" y="{220-h:.2f}" text-anchor="middle">{str(v).replace(".",",")}</text><text x="{x+24}" y="258" text-anchor="middle">{year}</text>')
    rows=''.join(f'<tr><th scope="row">{y}</th><td>{str(v).replace(".",",")}</td></tr>' for y,v in zip(years,values))
    return '<figure class="aral-data-figure"><svg viewBox="0 0 720 290" role="img" aria-label="'+e(caption,quote=True)+'"><text x="25" y="22">'+e(unit)+'</text><path d="M70 40V235H690" fill="none" stroke="#17243a"/><text x="52" y="240">0</text>'+''.join(paths)+'</svg><figcaption>'+e(caption)+'</figcaption></figure><table><caption>Valeurs exactes · '+e(unit)+'</caption><thead><tr><th scope="col">Année</th><th scope="col">Valeur</th></tr></thead><tbody>'+rows+'</tbody></table>'

def document(id,title,nature,date,author,source,description,shows,limits,tags,**kwargs):
    return dict(id=id,title=title,nature=nature,date=date,author=author,source=source,description=description,shows=shows,limits=limits,tags=tags,credit='Notice et visualisation originales THOT, d’après la source indiquée.',license='Texte de lecture original ; données factuelles citées, document source non reproduit.',**kwargs)

aral=[]
a=document('d01','Les bateaux de Moynaq','Photographie documentaire','20 mars 2011','Sebastian Kluger',MOY,'Deux bateaux photographiés à Moynaq, en Ouzbékistan, sur un sol sec. Le fichier photographique est conservé sans retouche.','L’emplacement des bateaux est à sec au moment de la prise de vue.','La photographie seule ne donne ni la date du recul de l’eau, ni son étendue totale, ni ses causes. Elle ne permet pas de décrire la situation actuelle de chaque bassin.',['observation'],media={'src':'/Thot/assets/explorer-v2/media/moynaq-original.jpg','alt':'Deux bateaux échoués sur un sol sec à Moynaq, photographiés en mars 2011.'})
a.update(credit='Photographie Sebastian Kluger · Wikimedia Commons · fichier original intact ; cadrage d’affichage réversible.',license='CC BY-SA 3.0',license_url=BYSA);aral.append(a)
for id,year,date in [('d02','2000','25 août 2000'),('d03','2014','19 août 2014')]:
    a=document(id,'La mer vue de l’espace · '+year,'Image satellite Terra / MODIS',date,'NASA Earth Observatory',NASA,'Vue datée de la série World of Change. La ligne jaune de la source repère approximativement le rivage de 1960.','En 2000, le Nord et le Sud sont séparés ; le Sud comprend plusieurs lobes.' if year=='2000' else 'En août 2014, le bassin oriental de l’Aral du Sud est asséché ; de l’eau subsiste ailleurs.','Deux vues d’été permettent de comparer des états, pas d’en déduire seules un mécanisme causal. Couleurs, sédiments et profondeur changent ; une zone sèche à une date ne prouve pas un assèchement définitif.',['observation','evolution'],media={'src':'/Thot/assets/explorer-v2/media/aral-'+year+'.jpg','alt':'Image satellite de la mer d’Aral datée du '+date+' ; rivage de 1960 repéré en jaune.'})
    a.update(credit='NASA Earth Observatory · images MODIS du satellite Terra · fichiers de la série conservés.',license='Média NASA réutilisé selon les règles NASA, sans suggestion de soutien à THOT.',license_url=NASARIGHTS);aral.append(a)
# Le tracé des fleuves est produit séparément depuis les coordonnées Natural Earth.
river_svg=(OUT/'data/aral-rivers.svg').read_text(encoding='utf-8')
aral.append(document('d04','Deux fleuves, un lac sans débouché','Carte de repérage et fiche hydrologique','Géographie de repérage ; bilan décrit en 2011','Natural Earth ; Conrad et Kobildjanova',CORNELL,'L’Amou-Daria et le Syr-Daria alimentent le bassin. La mer d’Aral est un lac terminal : il n’a pas de sortie de surface vers un océan. Les apports des fleuves et de la pluie doivent être comparés à l’évaporation.','Moins d’eau atteignant le lac peut déséquilibrer son bilan hydrique, même sans augmentation de l’évaporation.','La carte représente des axes fluviaux modernes généralisés ; elle ne mesure pas les débits ni le fonctionnement de chaque canal. Le bilan est qualitatif, pas une simulation.',['hydrology'],visual_html=river_svg,additional_sources=[NE]))
aral.append(document('d05','La superficie à cinq dates','Visualisation originale de données publiées','1960, 1971, 1976, 1989, 2009','Conrad et Kobildjanova (2011), d’après Micklin (2010)',CORNELL,'Le tableau publié additionne toutes les parties de la mer d’Aral. Les barres reprennent cinq valeurs exactes, sans inventer d’état entre les dates.','La superficie totale rapportée passe de 67 499 km² en 1960 à 8 409 km² en 2009.','Ces mesures ne sont pas un relevé annuel et ne décrivent pas l’état en 2026. Additionner les bassins masque leurs trajectoires différentes. La série ne suffit pas à identifier une cause.',['evolution'],visual_html=bars([1960,1971,1976,1989,2009],[67499,60200,55700,39734,8409],'Superficie totale (km²)',70000,'Superficie, toutes les parties combinées. Barres à partir de zéro ; cinq observations, sans interpolation.')))
aral.append(document('d06','L’eau prélevée pour irriguer','Visualisation originale de statistiques','1960 à 2004','SIC ICWC',ICWC,'Le tableau de l’organisme régional présente les prélèvements dans le bassin. Ici, la série « Incl. irrigation » est exprimée en km³ par an.','Les prélèvements pour l’irrigation rapportés sont de 56,15 km³/an en 1960, 106,79 en 1980 et 93 en 2004. Ils ne progressent pas continuellement.','Un prélèvement n’est pas la totalité de l’eau consommée : des retours sont possibles. Ces chiffres ne mesurent pas directement le débit atteignant la mer. La corrélation avec sa superficie ne remplace pas l’explication hydrologique.',['irrigation'],visual_html=bars([1960,1970,1980,1990,2000,2004],[56.15,86.84,106.79,106.4,94.66,93],'Prélèvements pour irrigation (km³/an)',120,'Prélèvements à six dates, à l’échelle du bassin. Données SIC ICWC ; axe à partir de zéro.')))
aral.append(document('d07','Des cultures qui demandent de l’eau','Fiche de lecture scientifique et données','1960 à 2004 ; publication scientifique 2011','SIC ICWC ; Conrad et Kobildjanova',CORNELL,'À partir des années 1960, les programmes soviétiques d’irrigation développent notamment le coton. La superficie irriguée dans le bassin passe de 4 510 milliers d’hectares en 1960 à 8 120 en 2004 selon le SIC ICWC.','L’expansion de l’agriculture irriguée documente un usage majeur des eaux des fleuves. Le coton est important, mais d’autres cultures sont irriguées.','Ce total n’est pas une superficie de coton et n’attribue pas chaque prélèvement à une culture. Il ne suffit pas à évaluer les choix ou les besoins de chaque personne.',['irrigation'],additional_sources=[ICWC],visual_html='<div class="aral-stat-pair"><p><strong>4,51 millions ha</strong><br>irrigués en 1960</p><span aria-hidden="true">→</span><p><strong>8,12 millions ha</strong><br>irrigués en 2004</p></div>'))
aral.append(document('d08','Des années sèches qui aggravent le recul','Fiche de lecture de la série satellite','2005–2009 ; fluctuations 2009–2018','NASA Earth Observatory',NASA,'La NASA relie les forts reculs du lobe oriental du Sud entre 2005 et 2009 à une sécheresse qui réduit puis interrompt le débit de l’Amou-Daria. Entre 2009 et 2018, des années sèches et humides produisent des variations.','Le climat peut aggraver le manque d’apports et les niveaux ne baissent pas partout de façon régulière.','Ces variations à certaines dates n’établissent pas que le climat explique seul le recul depuis les années 1960. Il faut distinguer l’évolution de longue durée et les facteurs aggravants.',['climate','evolution']))
aral.append(document('d09','Quand le fond devient une source de poussières','Fiche de lecture institutionnelle','7 mai 2025','Programme des Nations unies pour le développement',UNDP,'Le PNUD décrit les tempêtes transportant sels et particules fines dans la région sud de la mer d’Aral. Ces poussières menacent la santé, l’agriculture et les écosystèmes. Le texte présente des travaux de modélisation et de végétalisation.','L’assèchement a des conséquences environnementales et humaines ; l’exposition et les réponses publiques font l’objet d’études.','Une menace régionale n’est pas un diagnostic médical individuel. Le document ne mesure pas ici la part exacte de chaque source de poussière et ne permet pas d’attribuer chaque maladie à la mer d’Aral.',['consequences']))
aral.append(document('d10','Au Nord, une restauration partielle','Fiche de lecture institutionnelle','Barrage achevé en août 2005 ; bilan octobre 2008','Banque mondiale',WB,'Le projet du Syr-Daria et de l’Aral du Nord comprend la digue de Kok-Aral. Le bilan de 2008 rapporte une remontée du niveau au Nord après l’achèvement de la digue en 2005 et une reprise des ressources aquatiques.','Une partie de la mer a une trajectoire différente : le Nord peut retenir davantage d’eau grâce à un aménagement.','Cette restauration ne reconstitue pas toute la mer de 1960. La digue modifie les échanges vers le Sud, et ce bilan daté ne garantit pas seul la situation actuelle.',['restoration','hydrology'],additional_sources=[NASA]))
dump('data/aral.json',{'title':'Le mystère de la mer d’Aral','documents':aral,'hypotheses':[{'id':'irrigation','title':'Les prélèvements pour l’irrigation jouent un rôle majeur.'},{'id':'climate','title':'Les variations climatiques suffisent à expliquer l’ensemble du recul.'},{'id':'disappearance','title':'Toute la mer d’Aral a définitivement disparu.'},{'id':'uncertain','title':'Je n’ai pas encore assez d’éléments pour conclure.'}],'hints':['Quelles pièces montrent une situation à une date, et lesquelles permettent de comparer deux états ?','Cherche le trajet de l’eau : d’où vient-elle, où est-elle prélevée, comment quitte-t-elle un lac sans débouché ?','Un changement de superficie ne donne pas à lui seul sa cause. Rapproche une observation d’un mécanisme.','Une explication peut distinguer cause principale, facteur aggravant et conséquence. Quelles pièces n’ont pas le même rôle ?','Compare le Nord et le Sud. Une affirmation sur « toute la mer » résiste-t-elle au dossier ?']})

REP=src('The Met · The Roman Republic (2000)','https://www.metmuseum.org/essays/the-roman-republic')
PUNIC=src('The Met · Western North Africa, 1000 B.C.–1 A.D.','https://www.metmuseum.org/pt/toah/ht/04/afw.html')
EMP=src('Christopher S. Lightfoot, The Met · The Roman Empire (2000)','https://www.metmuseum.org/essays/the-roman-empire-27-b-c-393-a-d')
# Le récit n’introduit pas de date cartographique supplémentaire.
chapters=[
 ('italy','Rome et la conquête de l’Italie',['bc400','bc300'],'Une cité parmi d’autres','Au IVe siècle av. J.-C., Rome n’est pas encore l’empire visible à la fin du parcours. Comparez deux états schématiques, vers 400 puis 300 av. J.-C.\nLes conquêtes et les alliances sont des relations de pouvoir différentes. Une couleur ne signifie pas que tous les habitants ont le même statut, la même langue ou les mêmes droits. Les contours de ces cartes mondiales sont très généralisés.',REP),
 ('punic','Rome face à Carthage : les guerres puniques',['bc300','bc200'],'La Méditerranée devient un enjeu','Les guerres puniques opposent Rome et Carthage au IIIe et au IIe siècle av. J.-C. Hannibal appartient à cette histoire : l’expansion n’est ni paisible, ni inévitable.\nL’état vers 200 av. J.-C. suit de près la deuxième guerre punique ; il ne représente pas la destruction de Carthage, survenue en 146 av. J.-C. Il n’existe pas ici d’état cartographique pour chacune des campagnes. Le portrait d’Hannibal proposé est une sculpture moderne, pas un témoignage visuel antique.',PUNIC),
 ('mediterranean','La domination s’étend en Méditerranée',['bc200','bc100'],'Gagner des territoires, gouverner des sociétés','Au cours des derniers siècles de la République, conquêtes et diplomatie étendent les territoires administrés hors d’Italie. Le récit du Met cite notamment la Sicile, l’Hispanie, l’Afrique et la Macédoine.\nCes gains n’apportent pas la même prospérité à tous. La répartition des richesses et des terres, les engagements militaires et les tensions politiques accompagnent l’expansion. La carte ne montre pas directement ces effets sociaux.',REP),
 ('caesar','César, les conquêtes et les crises de la République',['bc100','bc60','bc1'],'Un empire territorial avant le régime impérial','Rome domine déjà un grand espace sous la République. César participe aux conquêtes et aux conflits qui aboutissent à la concentration du pouvoir puis à son assassinat en 44 av. J.-C.\nL’atlas ne possède pas de carte exacte de chaque campagne de César : le passage de 60 à 1 av. J.-C. couvre plusieurs décennies. Il inclut des transformations postérieures à sa mort. Ne lui attribuez pas tous les territoires ajoutés entre ces deux états. Une monnaie est une source sur le message d’un pouvoir, pas une carte de ses conquêtes.',REP),
 ('augustus','Auguste et la naissance du régime impérial',['bc1'],'Changer de régime sans repartir de zéro','Octavien reçoit le titre d’Auguste en 27 av. J.-C. Le nouveau régime concentre des pouvoirs tout en conservant des institutions et des formes républicaines.\nLa carte disponible ici représente 1 av. J.-C., sous son règne ; ce n’est pas une carte de l’année 27. Le denier daté vers 29–27 av. J.-C. permet de regarder comment une image politique se construit au moment de cette transition.',EMP),
 ('trajan','Des premiers empereurs à Trajan',['ad100','ad117'],'L’apogée n’est pas une frontière éternelle','Sous Trajan, empereur de 98 à 117 apr. J.-C., Rome mène notamment des guerres en Dacie et contre les Parthes. L’extension de l’Empire atteint un sommet vers la fin de son règne.\nL’état AWMC de 117 est une reconstitution d’emprise, pas un relevé de chaque occupation militaire éphémère en Orient. Il ne prouve pas un contrôle uniforme ou durable. La source diffère de celle de 100 : leurs écarts de dessin ne sont pas tous des conquêtes. L’expansion implique également guerre, domination et résistances ; ce parcours s’arrête ici, sans suggérer que les frontières resteront fixes.',EMP)
]
people=[
 {'id':'hannibal','name':'Hannibal','dates':'247–vers 183 av. J.-C.','role':'Général carthaginois, adversaire de Rome pendant la deuxième guerre punique.','text':'Regarder l’expansion depuis Carthage permet de sortir d’un récit centré sur les seules victoires romaines. Cette sculpture de Sébastien Slodtz, réalisée en 1704 et conservée au Louvre (MR 2093), représente Hannibal selon une interprétation moderne. Elle n’atteste pas son apparence.','image':'/Thot/assets/explorer-v2/media/hannibal.webp','alt':'Sculpture moderne d’Hannibal par Sébastien Slodtz, 1704.','credit':'Photographie : Alain08, d’après Jastrow ; extraction Commons. Redimensionnement et conversion WebP THOT, sans retouche du sujet.','license':'CC BY-SA 3.0','license_url':BYSA,'source':src('Notice de l’œuvre et de la photographie, Commons','https://commons.wikimedia.org/wiki/File:Hannibal_Slodtz_Louvre_MR2093_(cropped2).png'),'limits':'Représentation moderne, non portrait antique.','additional_sources':[PUNIC]},
 {'id':'caesar','name':'Jules César','dates':'Fin de la République · mort en 44 av. J.-C.','role':'Général et homme politique de la fin de la République.','text':'Les conquêtes, les guerres civiles et la dictature de César appartiennent à la crise de la République. La carte de 1 av. J.-C. ne doit pas être lue comme le bilan de ses seules actions. Le portrait de Tusculum, conservé à Turin, est une œuvre antique attribuée à la fin de la République (vers les années 50–40 av. J.-C. dans la notice).','image':'/Thot/assets/explorer-v2/media/caesar.webp','alt':'Portrait antique dit de Tusculum, identifié comme Jules César.','credit':'Ángel M. Felicísimo · photographie via Wikimedia Commons. Redimensionnement et conversion WebP THOT.','license':'CC BY 2.0','license_url':'https://creativecommons.org/licenses/by/2.0/','source':src('Portrait de Tusculum, notice Commons','https://commons.wikimedia.org/wiki/File:Retrato_de_Julio_C%C3%A9sar_(26724093101).jpg'),'additional_sources':[REP],'limits':'Une identification de portrait et sa datation relèvent de l’étude de l’objet ; elles ne sont pas une photographie du personnage vivant.'},
 {'id':'augustus','name':'Auguste','dates':'Règne : 27 av. J.-C.–14 apr. J.-C.','role':'Premier empereur ; le titre d’Auguste lui est accordé en 27 av. J.-C.','text':'L’Auguste de Prima Porta est une statue antique conservée au Vatican. Sa posture, sa cuirasse et ses attributs participent à une représentation du pouvoir. Ce n’est pas une image neutre du quotidien de l’empereur. Le cliché de 2023 est distinct de l’ancienneté de l’œuvre.','image':'/Thot/assets/explorer-v2/media/augustus.webp','alt':'Statue antique d’Auguste de Prima Porta, photographiée au Vatican.','credit':'Justin Benttinen, 8 septembre 2023 · Commons. Version redressée par l’auteur ; redimensionnement et conversion WebP THOT.','license':'CC BY-SA 4.0','license_url':'https://creativecommons.org/licenses/by-sa/4.0/','source':src('Auguste de Prima Porta, Commons','https://commons.wikimedia.org/wiki/File:Augustus_of_Prima_Porta.jpg'),'additional_sources':[EMP],'limits':'Portrait de pouvoir antique, distinct d’une reconstitution moderne ou d’une photographie du règne.'},
 {'id':'trajan','name':'Trajan','dates':'Règne : 98–117 apr. J.-C.','role':'Empereur associé aux guerres de Dacie et d’Orient.','text':'Le portrait conservé à la Glyptothèque de Munich (inv. 336) provient d’une statue plus grande que nature. Cette tête antique rappelle que les représentations impériales occupent aussi l’espace public. Les contours de 117 ne suffisent pas à dire combien de temps chaque conquête a été contrôlée.','image':'/Thot/assets/explorer-v2/media/trajan.webp','alt':'Tête antique de Trajan, Glyptothèque de Munich, inventaire 336.','credit':'Bibi Saint-Pol, 8 février 2007 · Commons. Redimensionnement et conversion WebP THOT ; historique des adaptations disponible dans la source.','license':'Domaine public (photographie libérée par son auteur)','license_url':'https://creativecommons.org/publicdomain/mark/1.0/','source':src('Trajan, Glyptothèque, Commons','https://commons.wikimedia.org/wiki/File:Traianus_Glyptothek_Munich_336.jpg'),'additional_sources':[EMP]}
]
coins=[
 ('coin-caesar','248033','Denier de Jules César','47–46 av. J.-C.','Argent ; atelier indiqué en Afrique par le musée.','La notice identifie une tête de Vénus et, au revers, Énée portant Anchise et le palladium. Le nom CAESAR associe cette histoire à un acteur politique.','Le lieu d’émission est indiqué à l’échelle de l’Afrique par le musée ; aucune coordonnée précise d’atelier n’est inventée. Le lien avec Carthage ci-dessous est un repère régional de contexte, pas un lieu de découverte.','carthage'),
 ('coin-augustus','248037','Denier d’Octavien, futur Auguste','Vers 29–27 av. J.-C.','Argent ; Rome ou Brundisium selon le musée.','Le musée décrit la tête d’Octavien et un trophée sur une proue de navire. L’image montre un message de victoire, pas l’ensemble des expériences des populations dominées.','L’atelier est incertain : Rome ou Brundisium. Le rattachement à Rome n’est donc pas une identification certaine du lieu de frappe, ni un lieu de découverte.','roma'),
 ('coin-trajan','248042','Sesterce de Trajan','103–111 apr. J.-C.','Bronze ; atelier de Rome.','La notice décrit un buste de l’empereur et un pont au-dessus d’un fleuve, probablement le Danube. Les inscriptions célèbrent le pouvoir impérial.','L’identification du fleuve est proposée comme probable par le musée. Une monnaie ne prouve pas à elle seule la localisation exacte d’un pont.','roma')
]
documents=[]
for id,obj,title,date,nature,description,limits,place in coins:
    documents.append({'id':id,'title':title,'date':date,'nature':nature,'description':description,'text':description,'limits':limits,'image':'/Thot/assets/explorer-v2/media/met-'+obj+'.webp','alt':title+', photographie du Metropolitan Museum of Art.','credit':'The Metropolitan Museum of Art · Rogers Fund, 1908 · objet '+{'248033':'08.170.80','248037':'08.170.89','248042':'08.170.120'}[obj]+'. Redimensionnement et conversion WebP THOT.','license':'CC0 · Open Access / domaine public','license_url':'https://creativecommons.org/publicdomain/zero/1.0/','source':src('Notice et provenance de l’objet · The Met','https://www.metmuseum.org/art/collection/search/'+obj),'place_id':place})
places=[]
for id,name,num,text,docids,personids in [
 ('roma','Roma · Rome',423025,'Centre politique de la République puis du régime impérial. Les monnaies associées renseignent des représentations du pouvoir ; elles ne sont pas présentées comme des trouvailles archéologiques faites ici.',['coin-augustus','coin-trajan'],['caesar','augustus','trajan']),
 ('carthage','Carthago · Carthage',314921,'Puissance méditerranéenne opposée à Rome pendant les guerres puniques. Le denier de César est associé à cette fiche comme contexte régional africain, plusieurs générations après ces conflits, et non comme une découverte locale.',['coin-caesar'],['hannibal']),
 ('athens','Athenae · Athènes',579885,'Un lieu du monde grec pour repérer l’extension de la domination romaine en Méditerranée orientale. Sa présence dans la carte ne signifie pas que son statut reste identique à toutes les dates.',[],[]),
 ('alexandria','Alexandria · Alexandrie',727070,'Un repère du monde hellénistique et de l’Égypte. Les cartes sont des états territoriaux distincts, pas un récit continu de toutes les transformations locales.',[],['augustus']),
 ('lyon','Lugdunum · Lyon',167717,'Ce repère localise le site, mais ne doit pas être pris pour une ville existant sous ce nom dès 400 av. J.-C. La couche de lieux est un index documentaire transchronologique.',[],[])
]:
    # Coordonnées vérifiées, conservées dans le registre des lieux.
    places.append({'id':id,'name':name,'pleiades_id':num,'text':text,'document_ids':docids,'person_ids':personids,'source':src('Pleiades · '+name,'https://pleiades.stoa.org/places/'+str(num)),'limits':'Point représentatif Pleiades, pas emprise urbaine ni preuve d’existence ou d’intégration à Rome à la date affichée.'})
dump('data/rome-content.json',{'chapters':[dict(id=id,title=title,steps=steps,description=description,body=body,source=source) for id,title,steps,description,body,source in chapters],'people':people,'documents':documents,'places':places,'bibliography':[REP,EMP,PUNIC],'layer_limits':'Seules les emprises, contours, autres ensembles présents dans la source et cinq lieux de repérage sont proposés. Ni voies ni batailles ne sont tracées sans données vérifiées. Les lieux sont un index transchronologique, pas une liste des villes romaines à chaque époque.'})
print('Corpus construit : 10 pièces Aral ; 6 chapitres, 4 personnages, 3 monnaies, 5 lieux romains.')
